import React from 'react';

function App() {
  return (
    <div style={{ padding: '20px', textAlign: 'center' }}>
      <h1>🎉 DevCare Stretch</h1>
      <p>개발자를 위한 AI 기반 맞춤형 운동 추천 시스템</p>
      <p>✅ React 앱이 성공적으로 실행되었습니다!</p>
    </div>
  );
}

export default App;
